namespace UDP_App;

/// <summary>
/// ICH M11 User Guidance lookup by C-code.
/// Generated from the ICH M11 Clinical Electronic Structured Harmonised Protocol specification.
/// </summary>
public static class FieldGuidance
{
    public static readonly Dictionary<string, string> Guidance = new()
    {
        { "C115467", @"This section should detail the methods used for the determination of the sample size. The sample size calculation should be aligned with the primary estimand(s) and the primary analysis; otherwise, a justification is needed. Details of sample size calculation should include all relevant information to enable reproduction of the sample size, e.g.: * references to any prior studies on which assumptions were based * significance level (including information on the choice of one- or two-sided level) * power * assumed treatment effect and variability * how dropout rate and intercurrent events have been incorporated into sample size calculation * precision of estimator/length of confidence interval Any assumptions made should be stated and justified. Further analysis of how deviations from the assumptions will affect the sample size should be included. If complex simulations were used to calculate the sample size, consider including details in a separate simulation report as an appendix to the protocol. If the planned sample size is not derived statistically, then this should be explicitly stated along with a rationale for the intended sample size (e.g., exploratory nature of pilot trials; pragmatic considerations for trials in rare diseases)." },
        { "C115525", @"Describe storage and handling requirements (e.g., protection from light, temperature, humidity) for the investigational trial intervention(s). For trials in which multidose vials are utilised, provide additional information regarding stability and expiration time after initial use (e.g., if the seal is broken). Explain how the investigational trial intervention will be provided to the investigator. If applicable, include details about kits, packaging, or other material of the investigational trial intervention for blinding purposes. If the instructions are lengthy or complicated, it is acceptable to reference the package insert (if applicable) or include instructions in separate documents provided to the site (e.g., a pharmacy manual) and reference the separate documents." },
        { "C132346", @"The protocol should have a descriptive title that identifies the scientific aspects of the trial sufficiently to ensure it is immediately evident what the trial is investigating and on whom, and to allow retrieval from literature or internet searches." },
        { "C132349", @"The schedule of activities must capture the procedures that will be accomplished at each trial visit, and all contact with participants (e.g., telephone contacts). This includes any tests that are used for eligibility, participant randomisation or stratification, or decisions on trial intervention discontinuation. Allowable windows should be stated for all visits and procedures. A tabular format is recommended. When applicable for studies with extensive sampling (e.g., serial PK sampling), a separate table may be added." },
        { "C132351", @"A unique alphanumeric identifier for the trial, designated by the sponsor." },
        { "C132352", @"Move the Overview of Changes table from the previous amendments to this section in reverse chronological order (most recent first)." },
        { "C142582", @"Describe any interim analyses and criteria for stopping or adapting the trial. Ensure alignment with Section 4.3 Trial Stopping Rules. The description should include, but is not limited to, the following. Under circumstances where interim analysis details could impede the integrity of the trial, some of the information can be added in other documents outside of the protocol. * any planned interim analysis, even if it is only to be performed at the request of an oversight body (for example, DMC) * the purpose of the interim analysis, including whether the interim analysis may be used for stopping and/or other trial adaptations (e.g., sample size re- estimation, alteration to the proportion of participants allocated to each trial group, or changes to eligibility criteria) * the applied statistical method (e.g., group sequential test) and spending function (e.g., O'Brien-Fleming), as applicable * the parties responsible for performing and reviewing the results of the analyses (e.g., DMC, independent statistician) * when the analyses will be conducted (timing and/or triggers) * the decision criteria-statistical or other-that will be adopted to judge the interim results as part of a guideline for early stopping or other adaptations * who will see the outcome data while the trial is ongoing * whether these individuals will remain blinded to trial groups * how the integrity of the trial will be protected (e.g., maintaining blinding) when decisions are made after interim analyses (e.g., a decision to continue the trial or implement a specific adaptation)" },
        { "C142585", @"Further clarification: * Control Description: if active comparator or low dose, pick nonproprietary name or International Nonproprietary Name; indicate ""Not applicable"" if not applicable" },
        { "C142698", @"If applicable, describe any trial-specific stopping rules, including guidance on when the trial should be stopped for efficacy or safety reasons, when a cohort or dose escalation should be terminated, and/or when a given treatment arm should be terminated. If applicable, describe any rules that may result in a temporary pause of dosing and/or enrollment into the trial and criteria for restarting enrollment. Ensure that the trial-specific stopping rules are aligned with the specifications that are described in Section 10.9 Interim Analyses." },
        { "C142705", @"if not using below optional subheadings." },
        { "C146997", @"Explain why the trial is needed, and why the research questions being asked are important. Do not restate the objectives or estimands. Do not restate the IB; rather, cross reference to the IB as applicable to the description." },
        { "C147139", @"Describe the overall trial design and intervention model (e.g., single group, parallel group, cross-over, factorial, sequential), the expected number of participants, and the control method (e.g., placebo, active comparator, low dose, external, standard of care, sham procedure, or none [uncontrolled]). If there are any key aspects of the investigational trial intervention that inform the selection of the intervention model, this should be described. If applicable, indicate other design characteristics (e.g., superiority, noninferiority, dose escalation, or equivalence). If the trial will have an adaptive or novel design (e.g., the trial will be conducted under a master protocol), provide a summary of these design aspects. If applicable, describe within-trial transition rules (e.g., transitions involving cohorts or trial parts). Dose escalation or dose-ranging details should also be described." },
        { "C154628", @"Include any specific instructions for the collection and interpretation of vital signs." },
        { "C168186", @"Include any specific instructions for the collection, interpretation, and archiving of ECGs." },
        { "C176267", @"Describe the accountability method, including: * how the investigational trial intervention will be distributed * who will distribute the investigational trial intervention * participation of a drug storage repository or pharmacy, if applicable * plans for disposal or return of unused product * plans for reconciliation of investigational trial intervention, if applicable" },
        { "C176274", @"Describe any preparation of the investigational trial intervention, and when necessary, who should prepare it. When applicable, describe the maximum hold time once thawed/mixed before administration. Include thawing, diluting, mixing, and reconstitution/preparation instructions. For drug/device combination products, include any relevant assembly or use instructions and reference the package insert that is provided separately. If the instructions are lengthy or complicated, it is acceptable to reference the package insert (if applicable) or include instructions in separate documents provided to the site (e.g., a pharmacy manual) and reference the separate documents." },
        { "C176849", @"This section does not apply to COAs. Include this section only for any value evidence and outcomes assessments not included in either the efficacy or safety sections. Describe the health outcome measures, collection method (e.g., diary, physician interview), and participant burden." },
        { "C179373", @"Describe screen failure and indicate how screen failure will be handled in the trial, including conditions and criteria under which rescreening is acceptable. If applicable, indicate the circumstances and time window under which a repeat procedure is allowed for screen failure relating to specific inclusion/exclusion criteria for the trial." },
        { "C181232", @"For use by the sponsor at their discretion." },
        { "C181233", @"?? Enter the section number and name from the protocol Table of Contents that this amendment row applies to. Required when an amendment is present." },
        { "C181236", @"Insert the sponsor's confidentiality statement, if applicable; otherwise delete." },
        { "C184390", @"Specify the key elements of the informed consent process, including any special needs and how these are addressed (e.g., assent, capacity, legally acceptable representative, adolescents who may reach age of majority during the trial, pregnant participants and pregnant partners of participants)." },
        { "C184397", @"References should be listed in a common format that includes all relevant information to identify the source and date published. If a reference is not published, this should be clearly indicated." },
        { "C188853", @"List of key characteristics, such as demographic characteristics (e.g. age, sex) and clinical characteristics (e.g. prior therapies, symptoms, severity, biomarker status)" },
        { "C188856", @"Enter Description of Intercurrent Event" },
        { "C188857", @"Description of the strategy to address the intercurrent event (e.g., a treatment policy strategy); cross reference the justification in Section 4 Trial Design. If there is >1 intercurrent event for an objective, add additional intercurrent event rows" },
        { "C189349", @"Describe measures that will be used to maintain blinding: * The investigational trial interventions are as indistinguishable as possible * Plans for the maintenance of randomisation codes and appropriate blinding for the trial * Procedures for planned (e.g., interim analysis) and unintentional (e.g., breach of procedure) breaking of randomisation codes For unplanned but intentional actions (e.g., safety events), refer to Section 6.7.4 Emergency Unblinding at the Site. If the trial allows for some investigators or other designated staff to remain unblinded (e.g., to allow them to adjust investigational trial intervention), the means of maintaining the blinding for other investigators or staff should be explained. Measures to prevent unblinding by laboratory measurements or while performing study assessments, if used, should be described." },
        { "C20108", @"For an amendment that does not apply to all sites in the trial, select ""Not Global"" and utilise one of the identifiers based on amendment scope." },
        { "C20989", @"Include any specific instructions for the collection and interpretation of physical examinations." },
        { "C215629", @"Provide a rationale for the trial intervention model described in Section 4.1 Description of Trial Design with a cross reference to Section 6.2 Rationale for Investigational Trial Intervention Dose and Regimen. Rationale for choice of comparator, if applicable, should be described separately in Section 4.2.3 Rationale for Control Type. A rationale for the choice of trial population should be described separately in Section 5.1 Description of Trial Population and Rationale." },
        { "C217358", @"Specify any AESI, including: * any event (serious or nonserious) of scientific and medical concern relative to the trial intervention, for which ongoing monitoring and rapid communication by the investigator to the sponsor can be appropriate *    other events that merit reporting to the sponsor, trial leadership, IRB, and regulatory agencies Include the following for each AESI: *    the definition *    the approach for ascertaining information * if applicable, any approach to confirm or adjudicate the event" },
        { "C218475", @"Intervention Assignment Method: If applicable, describe the type of randomisation to be used (e.g., simple randomisation, block randomisation). If applicable, describe the other intervention assignment method" },
        { "C218476", @"Specify the AE definitions, including: * any relevant regional AE requirements * any events that meet and do not meet the AE definition * any trial-specific AE clarifications * if applicable, any clarifications on the AE and SAE definitions for efficacy trials (e.g., lack of efficacy or failure of pharmacological actions)" },
        { "C218477", @"Move the Overview of Changes table from the previous amendments to this section in reverse chronological order (most recent first)." },
        { "C218478", @"Enter the approximate number or percentage of participants enrolled as a percentage of the expected total sample size. Enter the actual number enrolled at the time of data lock or trial completion when applicable." },
        { "C218479", @"?? Select the section number and name from the protocol Table of Contents affected by this amendment row." },
        { "C218480", @"Describe the statistical analysis methods will be used to evaluate the secondary objective(s) and associated estimand(s) in Section 3.2 Secondary Objective(s) and Associated Estimand(s). Use the same section structure as Section 10.4 Analyses Associated with the Primary Objective(s). Include additional level 3 headings for each secondary objective as needed. If there is more than one secondary objective, number each objective consecutively as the level 3 heading (e.g., Secondary Objective 1, Secondary Objective 2, etc.). No text is intended here (heading only) unless there is no secondary objective, in which case indicate ""Not applicable.""" },
        { "C218483", @"?? Describe the change made in this amendment row. Required when an amendment is present." },
        { "C218484", @"All versions should be uniquely identifiable." },
        { "C218672", @"?? Select ""Yes"" if this is the original protocol (not an amendment), or ""No"" if this document is an amendment to a previously issued protocol." },
        { "C218674", @"For an amendment that does not apply to all sites in the trial, select ""Not Global"" and utilise one of the identifiers based on amendment scope." },
        { "C218675", @"Enter the sponsor's unique identifier for investigational product(s) in the trial. Add fields as needed." },
        { "C218677", @"Provide the legal name and address of the individual or pharmaceutical or medical device company, governmental agency, academic institution, private organisation, or other organisation who takes primary responsibility for and initiates a clinical investigation. If more than one sponsor, list the primary sponsor in the Sponsor Name and Sponsor Legal Address fields. If co-sponsor is applicable, enter co-sponsor name and legal address. Add additional fields if more than one co-sponsor is applicable." },
        { "C218678", @"Provide the legal name and address of the individual or pharmaceutical or medical device company, governmental agency, academic institution, private organisation, or other organisation who takes primary responsibility for and initiates a clinical investigation. If more than one sponsor, list the primary sponsor in the Sponsor Name and Sponsor Legal Address fields. If co-sponsor is applicable, enter co-sponsor name and legal address. Add additional fields if more than one co-sponsor is applicable." },
        { "C218679", @"Provide the legal name and address of the individual or pharmaceutical or medical device company, governmental agency, academic institution, private organisation, or other organisation who takes primary responsibility for and initiates a clinical investigation. If more than one sponsor, list the primary sponsor in the Sponsor Name and Sponsor Legal Address fields. If co-sponsor is applicable, enter co-sponsor name and legal address. Add additional fields if more than one co-sponsor is applicable." },
        { "C218680", @"In some countries, the clinical trial Sponsor may be the local affiliate company (or designee). In such cases, indicate this in the Local Sponsor Name and Address Field." },
        { "C218681", @"In some countries, the clinical trial sponsor may be the local affiliate company (or designee). In such cases, indicate this in the Local Sponsor Name and Local Sponsor Legal Address Fields." },
        { "C218682", @"Manufacturer name and address information is required only for drug/device combination protocols that include investigational device(s) and should not be included for other protocols. Include the manufacturer address only if the manufacturer is different than the sponsor listed above. Add additional fields as needed if multiple investigational devices will be used in the trial or if there are multiple manufacturers for a single device. Delete this line if not applicable." },
        { "C218683", @"Manufacturer name and address information is required only for drug/device combination protocols that include investigational device(s) and should not be included for other protocols. Include the manufacturer address only if the manufacturer is different than the sponsor listed above. Add additional fields as needed if multiple investigational devices will be used in the trial or if there are multiple manufacturers for a single device. Delete this line if not applicable." },
        { "C218693", @"?? Enter the Medical Expert contact information directly, or provide the location within the protocol where it can be found." },
        { "C218694", @"Choose the applicable statement below. For an original protocol that has not been amended, retain the first statement below and delete the remainder of this entire section. {This protocol has not been amended.} Or {This is the first protocol amendment.} Or include the below {This protocol has been amended previously. Details of prior amendments are presented in Section 12.3 Prior Protocol Amendment(s).}" },
        { "C218698", @"?? Indicate whether this amendment is likely to have a substantial impact on the safety or rights of participants (Yes or No)." },
        { "C218699", @"?? If the amendment is likely to have a substantial impact on participant safety or rights, briefly explain the nature of that impact." },
        { "C218700", @"?? Indicate whether this amendment is likely to have a substantial impact on the reliability and robustness of the data generated in the clinical trial (Yes or No)." },
        { "C218701", @"?? If the amendment is likely to have a substantial impact on data reliability or robustness, briefly explain the nature of that impact." },
        { "C218704", @"?? Select whether the trial will be conducted at a single centre or multiple centres (multicentre)." },
        { "C218705", @"?? Indicate whether this is a master protocol that will govern multiple sub-studies or substudies of different investigational products." },
        { "C218710", @"State the expected number of participants to be assigned to trial intervention/enrolled. Indicate whether the number provided is the target or maximum number of individuals to be randomly assigned to trial intervention/enrolled." },
        { "C218711", @"State the expected number of participants to be assigned to trial intervention/enrolled. Indicate whether the number provided is the target or maximum number of individuals to be randomly assigned to trial intervention/enrolled" },
        { "C218712", @"Select one of the two options for total planned duration of trial intervention and trial participation for each participant. Note that the total duration of trial participation should include any washout and any follow-up periods in which the participant is not receiving a trial intervention. When duration will vary, provide a short explanation (e.g., ""event-driven"" or ""adaptive design"")." },
        { "C218713", @"Select one of the two options for total planned duration of trial intervention and trial participation for each participant. Note that the total duration of trial participation should include any washout and any follow-up periods in which the participant is not receiving a trial intervention. When duration will vary, provide a short explanation (e.g., ""event-driven"" or ""adaptive design"")." },
        { "C218715", @"Select one of the two options for total planned duration of trial intervention and trial participation for each participant. Note that the total duration of trial participation should include any washout and any follow-up periods in which the participant is not receiving a trial intervention. When duration will vary, provide a short explanation (e.g., ""event-driven"" or ""adaptive design"")." },
        { "C218716", @"Select one of the two options for total planned duration of trial intervention and trial participation for each participant. Note that the total duration of trial participation should include any washout and any follow-up periods in which the participant is not receiving a trial intervention. When duration will vary, provide a short explanation (e.g., ""event-driven"" or ""adaptive design"")." },
        { "C218718", @"Indicate whether any committee(s) will be reviewing data while the trial is ongoing, and the type of committee. Common examples include Data Monitoring Committee, Dose Escalation Committee, or Endpoint Adjudication Committee; describe others, if applicable. List independent committees in the space indicated. Other committees may be included in the separate space provided. Committees listed here should be fully described in Section 11.4 Committees." },
        { "C218720", @"The purpose of this section is to provide a visual depiction of the trial design, orienting users of the protocol to the key features of the design. The schema depicts the trial arms, the flow of individual participant through the progression of trial period(s)/epochs (such as screening, washout/run-in, intervention, and key milestones [e.g., randomisation, cross-over, end of treatment, end of study, post-treatment follow-up]). For complex trials, additional schemas may be added to describe activities or trial periods in greater detail." },
        { "C218721", @"Trial Intervention - Describe risks related to trial-specific treatments and interventions. For the protocol, focus on the relevant key risks for this trial. Provide a brief description of strategies to mitigate identified risks or provide a cross reference to the relevant protocol section." },
        { "C218722", @"Trial Procedures - Describe risks associated with the design (e.g., placebo arm) and procedures specific to this trial (e.g., biopsies), and any measures to control or mitigate the risks. Provide a brief description of strategies to mitigate identified risks or provide a cross-reference to the relevant protocol section. This is not intended to be an exhaustive list of all possible risks associated with trial procedures but should focus on the unique risks inherent in the design or less common or high-risk procedures." },
        { "C218723", @"Other - Consider risks associated with other items (e.g., challenge agents, imaging agents, medical devices). This could include discussion of risk mitigation for special populations, if not described elsewhere. Insert a line for each, as needed." },
        { "C218724", @"The benefit summary should describe any physical, psychological, social, or other potential benefits to individual participants as a result of participating in the trial, addressing immediate potential benefits and/or long-range potential benefits. Clearly state if no benefits to an individual participant can be anticipated, or if potential benefits are unknown. For early clinical trials such as Phase 1 or trials in healthy participants, benefits for an individual participant (other than those of altruism) are expected to be minimal. Benefits to society in general may also be included but should be described separately from the individual participant perspective." },
        { "C218725", @"Provide a succinct, concluding statement on the perceived balance between risks that have been identified from cumulative safety data, protocol procedures, and anticipated efficacy/benefits within the context of the proposed trial." },
        { "C218726", @"Describe the trial duration with reference to Section 1.2 Trial Schema. Explain what the overall duration for an individual participant is anticipated to be and why, including the sequence and duration of trial periods (e.g., screening, run-in, randomisation, treatment [fixed dose/titration], follow-up/washout periods). Where applicable, include discussion of sentinel dosing (or lack thereof), dose escalation, and cohort expansion. If dose modification decisions are dependent upon review by a committee, include details in Section 11.4 Committees." },
        { "C218727", @"State the method of assignment to trial intervention and the level and method of blinding that will be used, with cross reference to Section 6.7 Investigational Trial Intervention Assignment, Randomisation and Blinding." },
        { "C218728", @"Describe any other important aspects of the design, e.g.: * geographic scope of trial (e.g., single-centre, multicentre, or multicentre and multinational) * use of decentralised elements in the trial * planned use of a Data Monitoring Committee, or similar review group and cross reference Section 11.4 Committees, for details * whether an interim analysis is planned; if so, refer to details in Section 10.9 Interim Analyses * any planned extension trial, long-term follow-up/registry, future use of samples or data, or post-trial sample analysis or other data-related activities" },
        { "C218729", @"If applicable, describe any stakeholder (e.g., patient, healthcare professional and patient advocacy groups) involvement in the design of the trial and any suggestions implemented." },
        { "C218730", @"When estimands are associated with the Primary and Secondary Objectives described in Section 3 Trial Objectives and Associated Estimands, provide a rationale for the estimand(s) not described elsewhere in the document. This should include a rationale that the selected endpoint(s) are clinically relevant and provide a reliable and valid measurement of the intended intervention effect(s). It should also include a rationale for the selected strategies for handling intercurrent events." },
        { "C218731", @"If applicable, provide a rationale for the type and choice of control selected for the trial (e.g., placebo, active drug, combination, external). Describe any known or potential problems associated with the control group selected in light of the specific disease and intervention(s) being studied. If comparators will differ by region, describe. The rationale for dose and/or dose regimen is explained in Section 6.2 Rationale for Investigational Trial Intervention Dose and Regimen." },
        { "C218732", @"Provide a rationale that the trial duration is appropriate for a reliable and relevant evaluation of the trial intervention per the trial objective(s)." },
        { "C218733", @"If applicable, provide a rationale for the use of an adaptive or novel design." },
        { "C218734", @"If applicable, provide a rationale for any interim analysis planned with respect to its purpose (e.g., stopping the trial early for efficacy or futility) and timing." },
        { "C218735", @"Discuss rationale for any additional aspects of the design not addressed above." },
        { "C218736", @"Define key timepoints in the trial, including trial start and end definitions (e.g., a key timepoint definition for start of trial might be when the ICF is signed by the first participant, and a key timepoint definition for end of trial might be when participants are no longer being examined or the last participant's last trial assessment has occurred). Consider local regulatory requirements for these and other definitions (e.g., the first act of recruitment). If appropriate, provide a cross reference to Section 11.11 Early Site Closure." },
        { "C218737", @"Define key timepoints in the trial, including trial start and end definitions (e.g., a key timepoint definition for start of trial might be when the informed consent is signed by the first participant, and a key timepoint definition for end of trial might be when participants are no longer being examined or the last participant's last trial assessment has occurred). If applicable, consider local regulatory requirements for these and other definitions (e.g., the first act of recruitment). If appropriate, provide a cross reference to Section 11.11 Early Site Closure." },
        { "C218738", @"If applicable, describe any possibilities for access to trial intervention, if any, beyond completion of the trial. Planned extension trials, if described in Section 4.1 Description of Trial Design, do not need to be repeated in this section." },
        { "C218740", @"Specify the definitions of: * participant of childbearing potential * participant of nonchildbearing potential" },
        { "C218741", @"Specify the: * contraceptive methods required * duration of use" },
        { "C218742", @"In the following subsections, describe any restrictions during the trial pertaining to lifestyle and/or diet, intake of caffeine, alcohol, or tobacco, or physical and other activities. If not applicable, include a statement that no restrictions are required." },
        { "C218743", @"If applicable, describe any restrictions on diet (e.g., food and drink restrictions, timing of meals relative to dosing, etc.)." },
        { "C218744", @"If applicable, describe any restrictions on the intake of caffeine, alcohol, tobacco, or other restrictions." },
        { "C218745", @"If applicable, describe any restrictions on physical activity (e.g., participants may be required to remain in bed for 4 to 6 hours after dosing)." },
        { "C218746", @"If applicable, describe restrictions on any other activity (e.g., blood or tissue donation, driving, heavy machinery use, or sun exposure)." },
        { "C218747", @"Trial interventions are all pre-specified investigational and noninvestigational medicinal products, medical devices or other interventions intended for the participants during the trial. The investigational trial intervention is the product(s) used in the trial as part of trial objectives, including control(s) (e.g., active comparator, placebo). Description of the investigational trial intervention is provided in Section 6.1 Description of Investigational Trial Intervention. Other trial interventions that are not part of trial objectives or do not have an investigational role in this trial are described in Section 6.9 Description of Noninvestigational Trial Intervention. Any regional requirements should be noted in the appropriate subsections. Provide an overview of investigational and noninvestigational trial interventions. Designate the trial intervention as IMP or NIMP/AxMP based on trial design and regional requirements. Consider the optional table below." },
        { "C218751", @"Describe the investigational trial intervention to be administered in each arm of the trial and for each period of the trial including route and mode of administration, dose, dosage regimen, duration of intervention, use, packaging and labelling. Refer to approved regional labelling, as appropriate. For investigational drug/device combination products, include details on the configuration and use of the device and device manufacturer. A device user manual may be referenced in this section." },
        { "C218752", @"Provide a rationale for the selection of the dose(s) or dose range, pharmaceutical dose form, route of administration, and dosing regimen of the investigational trial interventions, as applicable. This rationale should include relevant results from nonclinical studies and clinical trials that support selection of the dose and regimen. Discuss impact of differences in trial population characteristics (e.g., age, sex, race) that could lead to differences in pharmacokinetics and pharmacodynamics in this trial as compared to previous trials. If applicable, justify any differences in dose regimen or therapeutic use relative to approved labelling. Describe prior trials and other information that support the dose and/or dose regimen of the investigational trial intervention. Include a rationale for prospective dose adjustments incorporated in the trial, if any." },
        { "C218753", @"Describe the detailed procedures for administration of each participant's dose of each investigational trial intervention. This may include the timing of dosing (e.g., time of day, interval), the duration (e.g., the length of time participants will be administered the investigational trial intervention), and the timing of dosing relative to meals. Include any specific instructions on who, when or how to prepare and take the dose(s) and how to handle any delayed or missed doses. Dose escalation or cohort expansion as part of the overall design should be covered in Section 4.1 Description of Trial Design." },
        { "C218754", @"For each participant, describe any dose modifications allowed, including conditions for such dose modifications, particularly regarding failure to respond or safety concerns. State any minimum period required before a participant's dose might be raised to the next higher dose or dose range. Include whether it is permissible to start and stop treatment and how dose reductions (if permitted) are to be managed. Information on stopping investigational trial intervention for participants due to safety/other reasons should be described in Section 7 Participant Discontinuation of Trial Intervention and Discontinuation or Withdrawal from Trial." },
        { "C218755", @"Describe what is meant by investigational trial intervention overdose. Provide any available information on managing overdose and ensure it is consistent with the Investigator's Brochure or product labelling. Cross reference these documents as applicable." },
        { "C218756", @"State that at enrollment, participant identification codes should be assigned. Describe the method of assigning participants to investigational trial intervention without being so specific that blinding or randomisation might be compromised. If assignment to investigational trial intervention is by randomisation, describe when randomisation will occur relative to screening. If permuted block randomisation is employed, do not state the block size in the protocol. If adaptive randomisation or other methods of covariate balancing/minimisation are employed, include a cross reference to the methods of analysis in Section 10 Statistical Considerations. As applicable, details regarding the implementation of procedures to minimise bias should be described." },
        { "C218757", @"Describe the criteria for breaking the trial blind or participant code. Describe the circumstances that would require breaking the blind, either for an individual participant or for all participants, and specify who will be responsible for this decision. Include the procedure for emergency unblinding as well as documentation of unblinding. Indicate to whom the intentional and unplanned unblinding should be reported." },
        { "C218758", @"Describe the measures to monitor and document participants' adherence to investigational trial intervention (e.g., trial intervention accountability records, paper or electronic diaries, or investigational trial intervention concentration measurements). List what documents are mandatory to complete (e.g., participant drug log) and identify which records will be used as the source records for documenting investigational trial intervention adherence." },
        { "C218759", @"As stated in Section 6 Trial Intervention and Concomitant Therapy, noninvestigational interventions are pre-specified products used in the trial but are not part of trial objectives and hence, are not investigational trial interventions." },
        { "C218761", @"If applicable, describe the use of any other noninvestigational trial intervention (e.g., challenge agents or diagnostics)." },
        { "C218762", @"If applicable, describe any prohibited concomitant therapy." },
        { "C218763", @"If applicable, describe any permitted concomitant therapy." },
        { "C218764", @"Describe: * the criteria for discontinuation of a participant from any trial intervention, carefully evaluating which are appropriate for the trial population and therapy being studied * how participants who discontinue trial intervention will be followed after discontinuation. Depending on the chosen intercurrent event handling strategy, it will be important to continue to follow and ascertain outcomes in participants who discontinue trial intervention through the end of the trial to prevent missing data in important analyses. Refer to Section 1.3 Schedule of Activities for assessments to be performed at the time of and following discontinuation of trial intervention * the process for collecting and recording the detailed reasons for discontinuing trial intervention if not described elsewhere" },
        { "C218765", @"Describe: * the criteria for temporary discontinuation or interruption of trial intervention for an individual participant * what to do and which restrictions still apply if the participant has to temporarily discontinue or interrupt trial intervention * which assessments will be performed for the stated duration of the trial Details of any rechallenge or restart after temporary discontinuation of trial intervention due to a safety-related event should be included in Section 7.1.3 Rechallenge." },
        { "C218766", @"Describe the criteria for rechallenge/restarting trial intervention, how and when to perform rechallenge, the number of rechallenges allowed during the trial, and whether all, or specify which, assessments will be performed for the stated duration of the trial. If rechallenge is not allowed, state this." },
        { "C218767", @"Describe the criteria for participant discontinuation or withdrawal from the trial. Describe the reason for withdrawal and the type of data to be collected for the final assessments with reference to the schedule of activities for the participant's end of study visit unless provided in another section. In many cases, the only reason for a participant being considered withdrawn from the trial should be a participant's withdrawal of consent to continue to participate in the trial. All other participants, including those who discontinue trial intervention, should remain in the trial and continue to be followed to prevent missing data in important analyses. Refer to Section 10 Statistical Considerations for the data that must be collected for the trial estimands." },
        { "C218768", @"Describe how the trial will define how participants are lost to follow-up. In general, participants should be considered lost to follow-up only if they cannot be reached despite multiple attempts to contact them. Also describe approaches that will be used to minimise loss to follow-up, such as multiple, diverse methods to remain in contact with participants (e.g., telephone calls, texts, and emails to the participant) and how contacts will be recorded." },
        { "C218769", @"Describe general considerations applicable across trial assessments and procedures." },
        { "C218770", @"Describe any assessments and procedures that are unique to screening/baseline (e.g., collection of data on participant characteristics, assessments/procedures performed for the purpose of determining eligibility or for stratification) in this section. Describe screening and baseline assessments and procedures separately when screening and baseline are different or performed at different visits." },
        { "C218771", @"Describe any assessments and procedures that are unique to screening/baseline (e.g., collection of data on participant characteristics, assessments/procedures performed for the purpose of determining eligibility or for stratification) in this section. Describe screening and baseline assessments and procedures separately when screening and baseline are different or performed at different visits." },
        { "C218772", @"Describe efficacy assessments and procedures in this section. Cross reference Section 8.7 Immunogenicity Assessments if immunogenicity assessments are used in efficacy determination." },
        { "C218773", @"Describe safety assessments and procedures utilising the following subsections as applicable. Add level 3 headings as needed. *   Identify any noninvestigator party involved in the evaluation of laboratory or other safety assessments (e.g., sponsor or external Independent Data Monitoring Committee; cross reference Section 11.4 Committees for details as applicable). *   Include guidelines for the medical management of relevant laboratory or other safety assessment abnormalities." },
        { "C218774", @"Describe any specific instructions for the collection and interpretation of clinical laboratory assessments, including: *    type of laboratory (central/local/hybrid) *    acceptability of additional tests deemed necessary by the investigator or local regulations *    instructions for situations in which central laboratory results are not available in time for trial intervention and/or response evaluation, or in the event of a severe disruption (e.g., a pandemic or natural disaster) *    treatment algorithms for results out of normal range *    cross reference Section 12.1 Clinical Laboratory Tests for laboratory assessment panels" },
        { "C218775", @"If the trial meets any of the criteria requiring suicidal ideation and behaviour risk monitoring by the guidance/guideline in each region, include justification for the need for suicidal ideation and behaviour risk monitoring in the study and add any specific instructions for the collection and interpretation of the assessment. In case this is an AESI in the study, justification should also be provided in Section 9.2.4 Adverse Events of Special Interest." },
        { "C218776", @"Include any specific instructions for the collection and assay of samples and interpretation of PK assessments. *     Describe the biological samples collected, the handling of samples, and the assay method. o    Specific sample collection and processing instructions can be described in an appendix or a separate document and cross referenced. *     Describe the retention time for the samples (ensuring alignment with the ICF). *     Indicate the types of analyses for each sample. * Define the PK parameters to be calculated and the calculation methods." },
        { "C218777", @"Include any specific instructions for the collection and assay of samples for genetic, genomics, pharmacogenetics and/or pharmacogenomic analysis. *    Describe the biological samples that will be collected (e.g., tissue, serum, plasma), handling of samples, and the assay method. o Specific sample collection and processing instructions can be described in an appendix or a separate document and cross referenced. *    Describe the retention time for the samples (ensuring alignment with the ICF). * Indicate the types of analyses that may be studied for each sample." },
        { "C218778", @"Include any specific instructions for the collection of samples and assessment of pharmacodynamic biomarkers. *    Describe the biological samples that will be collected (e.g., tissue, serum, plasma). o Specific sample collection and processing instructions can be described in an appendix or a separate document and cross referenced. *    Describe the retention time for the samples (ensuring alignment with the ICF). *    Indicate the types of biomarkers that will be studied for each sample. *    Specify whether each sample is optional or required. Required samples must be based on a protocol objective." },
        { "C218779", @"Include any specific instructions for the collection of samples and assessment of other biomarkers. *    Describe the biological samples that will be collected (e.g., tissue, serum, plasma). o Specific sample collection and processing instructions can be described in an appendix or a separate document and cross referenced. *    Describe the retention time for the samples (ensuring alignment with the ICF). *    Indicate the types of biomarkers that will be studied for each sample. *    Specify whether each sample is optional or required. Required samples must be based on a protocol objective." },
        { "C218780", @"Include any specific instructions for the collection of samples and interpretation of immunogenicity. If immunogenicity assessments are included within Section 8.3 Efficacy Assessments and Procedures or Section 8.4 Safety Assessments and Procedures, cross reference that section. *    Describe the biological samples that will be collected (e.g., tissue, serum, plasma). o Specific sample collection and processing instructions can be described in an appendix or a separate document and cross referenced. *    Describe the retention time for the samples (ensuring alignment with the ICF). *   Indicate the types of biomarkers that will be studied for each sample. *   Specify whether each sample is optional or required. Required samples must be based on a protocol objective." },
        { "C218781", @"Specify the SAE definitions, including: * any relevant regional SAE requirements * any events that meet and do not meet the SAE definition * any trial-specific SAE clarifications" },
        { "C218782", @"Specify the definitions of product complaints in the context of the trial." },
        { "C218783", @"?? Provide the definition of Medical Device Product Complaints as they apply to this trial, consistent with the definition in Section 9.1.3 Product Complaints." },
        { "C218791", @"Specify timing for collection and reporting, including: *   start and end dates for collection and reporting *   frequency of collection and reporting * cross reference to the Schedule of Assessments as appropriate" },
        { "C218792", @"Specify how information will be identified (e.g., self-reported, solicited questions)." },
        { "C218793", @"Specify procedures for recording." },
        { "C218794", @"Specify the procedures for follow-up. Include the assessment tools that will be used to monitor the events and the duration of follow-up after appearance of the events." },
        { "C218795", @"Specify the reporting method (e.g., an electronic data collection tool or a paper CRF), backup reporting method, if applicable, and reporting timeline to the sponsor." },
        { "C218796", @"Specify: *   the investigator's responsibilities for reporting to the sponsor (and to ethics committees, where required), specifying timing of reporting to allow the sponsor to meet their responsibilities *   the sponsor's legal/regulatory responsibilities for reporting to regulatory authorities, ethics committees, and investigators * suspected unexpected serious adverse reaction reporting" },
        { "C218798", @"Specify: *    the assessments to be performed *    type and duration of monitoring *    whether participants who become pregnant during the trial may continue with trial intervention or must be discontinued from trial intervention (refer to Section 7 Participant Discontinuation of Trial Intervention and Discontinuation or Withdrawal from Trial as applicable) *    any trial modifications that need to be made for participants who become pregnant *    what information will be collected about a participant who becomes pregnant during the trial (e.g., recording and reporting to the sponsor, postpartum follow-up, trial intervention discontinuation or continuation, or trial withdrawal) For postpartum follow-up, include the time period (e.g., initial child development) with justification. If exposure to trial intervention during breastfeeding is applicable, specify: *    the assessments to be performed *    type and duration of monitoring * information to be collected for both the participant and child" },
        { "C218799", @"Specify: *    whether the investigator will attempt to collect pregnancy information about a participant's partner who becomes pregnant during the specified period in the trial *    whether the participant whose partner becomes pregnant should be discontinued from trial intervention (refer to Section 7 Participant Discontinuation of Trial Intervention and Discontinuation or Withdrawal from Trial as applicable) *    the assessments to be performed, type and duration of monitoring, and the information to be collected" },
        { "C218800", @"Specify special safety situations associated with the trial intervention(s) that do not qualify as an AE or SAE but require regulatory reporting. Examples include: *    misuse or abuse *    off-label use (if applicable) *    medication error (prescription or dispensing error) *    occupational exposure *    use outside of what is foreseen in the protocol *    unintended exposure of embryo, foetus, or child via maternal exposure (pregnancy or breastfeeding) or via paternal exposure (semen) *    lack of therapeutic efficacy; this is not applicable for studies that measure efficacy as a study endpoint *    suspected transmission of an infectious agent; this is only applicable for injected or biologic medicinal products *    product complaint, including falsified or counterfeit products * suspected drug-food or drug-drug interaction" },
        { "C218801", @"Describe analysis sets to be considered at the trial level, i.e., the set of participants whose data are to be included in the analyses, aligned with estimands. Clearly specify the analysis set to be used for each analysis described in Section 10 Statistical Considerations." },
        { "C218802", @"Describe the summary statistics that will be used to characterise the distribution of demographic and other relevant variables at baseline. Specify when the variables will be measured (e.g., at trial inclusion, prior to randomisation, or at the time of randomisation). Relevant variables include but are not limited to: stratification variables specified in Section 6.7 Investigational Trial Intervention Assignment, Randomisation and Blinding, covariates for the statistical models specified in Section 10.4 Analyses Associated with the Primary Objective(s), other suspected predictive or prognostic variables, and variables used for planned subgroup analyses." },
        { "C218803", @"For each intercurrent event of the primary estimand(s) defined in Section 3.1 Primary Objective(s) and Associated Estimand(s), explain how data will be handled for the statistical analysis in line with the primary estimand. The handling of intercurrent events in the statistical analysis should be aligned with the specific estimand strategies being used. This section should describe in more detail the rationale and handling of the data rather than repeating information from the preceding sections." },
        { "C218804", @"Describe how missing data will be addressed (e.g., imputation method and model), state the underlying assumptions, and provide a rationale for the approach." },
        { "C218808", @"If safety is a primary and/or secondary objective, describe the corresponding safety analyses in the appropriate section above (Section 10.4 Analyses Associated with the Primary Objective[s] or Section 10.5 Analyses Associated with the Secondary Objective[s]). In this section, describe statistical methods that will be used to analyse relevant safety outcomes, including any AESI. This should typically include specification of a measure to estimate risk within treatment arms, a measure to compare risks across treatment arms, and a measure of statistical uncertainty around the comparison (e.g., a confidence interval)." },
        { "C218809", @"Describe other analyses not included in Sections 10.3-10.7, such as subgroup analyses." },
        { "C218810", @"Multiple testing procedures may be needed to limit the probability of false positive findings in a trial. Reasons for carrying out multiple statistical tests include, but are not restricted to, multiple endpoints, multiple treatment groups, multiple hypotheses, subgroups, and multiple timepoints. Describe any approaches to multiplicity control for the trial. This description might go beyond the analysis of primary objectives. Specify the statistical approach to control the overall type I error rate as well as the (adjusted) significance levels to test specific hypotheses, as applicable. Clarify whether the tests/confidence intervals are one- or two-sided. State the circumstances under which a trial will be considered to have met its primary objective(s). For example, in a study with two primary efficacy endpoints, this section should state whether the study would be expected to provide statistical evidence on at least one or on both of the endpoints in order to confirm the efficacy of the treatment. For some statistical approaches it might be helpful to include a graphical depiction, as visualisation will be helpful for understanding, coupled with the clinical translation of the mathematical choices. Details regarding interim analyses should be provided in Section 10.9 Interim Analyses." },
        { "C218811", @"Provide a high-level statement on the prevailing ethical, legal, and regulatory guidelines that will be applied throughout the trial. This trial will be conducted in accordance with the protocol and with the following: * Ethical principles that have their origin in the Declaration of Helsinki for medical research involving human subjects * Consensus ethical principles derived from international guidelines including the Declaration of Helsinki and the Council for International Organisations of Medical Sciences (CIOMS) International Ethical Guidelines * ICH Good Clinical Practice (GCP) Guidelines * Applicable laws and regulations" },
        { "C218812", @"Concisely summarise the trial oversight, listing the investigator and sponsor responsibilities not covered in other sections of the protocol that are essential for trial conduct, specifying the ones related to quality assurance. if not using below optional subheadings." },
        { "C218813", @"Describe the investigator responsibilities, including the oversight of trial-related activities delegated to a third party that may impact the trial conduct at sites, if applicable and if not addressed elsewhere." },
        { "C218814", @"Describe the sponsor responsibilities, including activities to be transferred to a third party that may impact the investigator sites, if applicable." },
        { "C218815", @"Specify the key elements of the informed consent process, including any special needs and how these are addressed (e.g., assent, capacity, legally acceptable representative, adolescents who may reach age of majority during the trial, pregnant participants and pregnant partners of participants)." },
        { "C218816", @"If enrollment in the trial may occur during an emergency in which the participant or their legally acceptable representative is not able or available to give consent, describe the consent process." },
        { "C218817", @"If participants can be rescreened as described in Section 5.6 Screen Failure and Rescreening, state whether the participant needs to complete a new ICF. Screen failure and rescreening should be clearly defined in the protocol, with a cross reference to those definitions." },
        { "C218820", @"Concisely summarise the arrangements for participant insurance and indemnity if not addressed in a separate agreement, if required by the applicable regulatory requirements." },
        { "C218821", @"Describe the identified critical to quality factors, associated risks and risk mitigation strategies for the trial or refer to the location where this is described and updated during the trial based on emerging data." },
        { "C218822", @"Describe the key systems and processes for critical trial integrity, traceability and security including a summary of the approaches enabling accurate data collection, reporting, monitoring, transfer, retention, and access if not addressed in separate agreement(s)." },
        { "C218823", @"Describe the measures to protect the privacy and confidentiality of personal information of trial participants in accordance with applicable regulatory requirements on personal data protection and any measures that should be taken in case of a data security breach." },
        { "C218827", @"Describe plans for detecting, reviewing, and reporting any deviations from the protocol or include reference to a separate document." },
        { "C218828", @"List the sponsor's rights to close a site early. Likewise, list the investigator's rights to initiate early site closure." },
        { "C218829", @"List the criteria for early closure of a site by the sponsor or investigator." },
        { "C218830", @"List the responsibilities of the sponsor and investigator following early site closure (e.g., informing the ethics committee[s], and prompt notification of the participant and their transition to appropriate therapy and/or follow-up)." },
        { "C218831", @"Describe whether the clinical trial will be registered in public databases, including reporting of results, if applicable." },
        { "C218833", @"Although global clinical trial practices are increasingly harmonised, some country/ region-specific differences in requirements do exist (e.g., document retention periods, contraception requirements). Where differences in requirements cannot be reconciled, the sponsor should explain how they will document and communicate country/region-specific differences (e.g., by country/region-specific amendments or addenda). An alternative to country/region-specific amendments is to list the specific differences by country or countries in this section, including a reference to the relevant section of the protocol where the differing requirement applies." },
        { "C218835", @"Choose the applicable statement below. For an original protocol that has not been amended, retain the first statement below and delete the remainder of this entire section. {This protocol has not been amended.} Or {This is the first protocol amendment.} Or include the below as applicable. {This protocol has been amended previously. The Protocol Amendment Summary of Changes for the current amendment is located directly before the Table of Contents. Prior amendment(s) to this protocol are listed in the table below, beginning with the most recent.}" },
        { "C218836", @"?? If the overview of prior amendments is held in an alternative location rather than inline in this section, specify that location here." },
        { "C218837", @"Define abbreviations and other terms used in the protocol. A tabular presentation is common and may serve as the definition at first use." },
        { "C218838", @"If necessary, include any clarifications or cross-references to details in the main body of the protocol in the optional field below." },
        { "C218839", @"Summarise the primary and secondary objectives and any associated estimands in natural, nontechnical (layperson) language. For trials intended to estimate a treatment effect or test a hypothesis related to a treatment effect, include the primary and secondary objectives and any associated estimands using a nontechnical summary describing the objective and treatment effect of interest (estimand). For other types of trials not intended to estimate a treatment effect or test a hypothesis related to a treatment effect, define trial objectives and describe additional information relevant to the clinical question(s) of interest (e.g., the endpoint(s) associated with each objective). For trials with numerous objectives in which the description of objectives will exceed half a page, consider including the most important objectives and estimands in the synopsis and refer to Section 3 Trial Objectives and Associated Estimands, which covers the objectives and estimands in technical detail. For considerations on estimands, refer to ICH E9(R1)." },
        { "C219658", @"State the method of assignment to trial intervention and the level and method of blinding that will be used, with cross reference to Section 6.7 Investigational Trial Intervention Assignment, Randomisation and Blinding." },
        { "C222014", @"?? Enter the sponsor signatory information (name, title, signature and date) or the location within the document where this information can be found." },
        { "C222063", @"?? Enter the location within the protocol where Medical Expert contact information can be found, if not entered directly in the adjacent field." },
        { "C222064", @"?? Enter the location within the protocol where sponsor signatory information can be found, if not entered directly in the adjacent field." },
        { "C222263", @"?? Describe the situational scope for this row of the adverse event or other safety table, if applicable." },
        { "C222329", @"Describe any background intervention(s), including administration and any conditions for use." },
        { "C222330", @"List all permitted rescue medications, treatments, and/or procedures, including any relevant instructions on administration and any conditions of use. If administration of rescue therapy leads to the temporary or permanent discontinuation of trial intervention, refer to Section 7 Participant Discontinuation of Trial Intervention and Discontinuation or Withdrawal from Trial." },
        { "C222495", @"Provide the legal name and address of the individual or pharmaceutical or medical device company, governmental agency, academic institution, private organisation, or other organisation who takes primary responsibility for and initiates a clinical investigation. If more than one sponsor, list the primary sponsor in the Sponsor Name and Sponsor Legal Address fields. If co-sponsor is applicable, enter co-sponsor name and legal address. Add additional fields if more than one co-sponsor is applicable." },
        { "C223136", @"N/A." },
        { "C223137", @"Intervention Assignment Method: If applicable, describe the type of randomisation to be used (e.g., simple randomisation, block randomisation). If applicable, describe the other intervention assignment method" },
        { "C223138", @"Intervention Assignment Method: If applicable, describe the type of randomisation to be used (e.g., simple randomisation, block randomisation). If applicable, describe the other intervention assignment method." },
        { "C25196", @"Describe the randomisation procedures (e.g., central randomisation procedures), the method used to generate the randomisation schedule (e.g., computer generated), the source of the randomisation schedule (e.g., sponsor, investigator, or other), and whether IRT(s) will be used. To maintain the integrity of the blinding, do not include the block size." },
        { "C25212", @"Definition of the endpoint" },
        { "C25370", @"Add criteria as needed. Consider numbering the criteria sequentially." },
        { "C25532", @"Add criteria as needed. Consider numbering the criteria sequentially." },
        { "C25676", @"Specify the intensity rating categories/scale." },
        { "C42581", @"Briefly describe key changes. Changes that are included in the amendment but unrelated to the key changes do not need to be described here." },
        { "C48281", @"For trials combining investigational drugs or vaccines with devices, classify according to the phase of drug development." },
        { "C49236", @"List of key aspects of treatment regimens in each treatment group, including at least investigational agents, dosage, and administration route" },
        { "C49628", @"Describe screen failure and indicate how screen failure will be handled in the trial, including conditions and criteria under which rescreening is acceptable. If applicable, indicate the circumstances and time window under which a repeat procedure is allowed for screen failure relating to specific inclusion/exclusion criteria for the trial." },
        { "C49647", @"?? Select the type of control used in this trial (e.g., Placebo, Active Comparator, Dose Response, External, or Sham Comparator)." },
        { "C49658", @"For designs in which these details may differ in one or more trial periods, answer according to the portion of the trial in which the highest number of blinded roles occurs. Additional details can be provided in Section 6.7.3 Measures to Maintain Blinding." },
        { "C49692", @"State the expected number of participants to be assigned to trial intervention/enrolled. Indicate whether the number provided is the target or maximum number of individuals to be randomly assigned to trial intervention/enrolled." },
        { "C49693", @"Population Age: for trials in which multiple age ranges may be eligible (e.g., a younger cohort and an older cohort), indicate the minimum and maximum ages for the trial overall, with an additional comment for any excluded age ranges." },
        { "C49694", @"Population Age: For trials in which multiple age ranges may be eligible (for example, a younger cohort and an older cohort), indicate the minimum and maximum ages for the trial overall, with an additional comment for any excluded age ranges." },
        { "C50400", @"Population Age: For trials in which multiple age ranges may be eligible (for example, a younger cohort and an older cohort), indicate the minimum and maximum ages for the trial overall, with an additional comment for any excluded age ranges." },
        { "C53630", @"Specify the concomitant medications, supplements, complementary and alternative therapies, treatments, and/or procedures that are prohibited or permitted during the trial and include details about when the information will be collected (e.g., during screening, at each visit). When appropriate to separate the content, the below subheadings may be used." },
        { "C70833", @"List of key characteristics, such as demographic characteristics (e.g. age, sex) and clinical characteristics (e.g. prior therapies, symptoms, severity, biomarker status)" },
        { "C71898", @"Omit proprietary name field if not yet established." },
        { "C82552", @"Specify: * the causality categories/scale * procedures for assessing causality" },
        { "C85826", @"?? <strong>Required.</strong> Describe the primary objective of this study." },
        { "C85827", @"?? <strong>Optional.</strong> If provided, the Endpoint field becomes required." },
        { "C163559", @"?? <strong>Optional.</strong> If provided, the Endpoint field becomes required." },
        { "C83081", @"For an amendment that does not apply to all sites in the trial, select ""Not Global"" and utilise one of the identifiers based on amendment scope." },
        { "C92949", @"Include any specific instructions for the collection and interpretation of pregnancy testing." },
        { "C93682", @"The purpose of this section is to provide a visual depiction of the trial design, orienting users of the protocol to the key features of the design. The schema depicts the trial arms, the flow of individual participant through the progression of trial period(s)/epochs (such as screening, washout/run-in, intervention, and key milestones [e.g., randomisation, cross-over, end of treatment, end of study, post-treatment follow-up]). For complex trials, additional schemas may be added to describe activities or trial periods in greater detail." },
        { "C93813", @"For use by the sponsor at their discretion." },
        { "C94108", @"Acronym or abbreviation used publicly to identify the clinical trial. Delete this line from the table if not applicable." },
        { "C97054", @"Further clarification: * Control Description: if active comparator or low dose, pick nonproprietary name or International Nonproprietary Name; indicate ""Not applicable"" if not applicable" },
        { "C98746", @"?? Select the overall trial design type (e.g., Single Group, Parallel Group, Cross-over, Factorial, Sequential, or Other)." },
        { "C98771", @"Select the numeric value for the number of arms in the trial. For trials with a different number of arms in different periods, populate this field based on the total number of arms." },
    };

    public static string For(string code) =>
        Guidance.TryGetValue(code, out var g) ? g : string.Empty;
}
